'use strict';

/**
 * Produce a sample signed webhook request for local testing.
 *
 * Uses the local development private key generated by
 * `node scripts/generate-dev-keys.js`. Never run this against a production
 * provider or with real credentials.
 *
 * Usage: node scripts/sign-example.js
 */

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const privatePath = path.join(__dirname, '..', 'keys', 'dev-private.pem');

let privateKey;
try {
  privateKey = crypto.createPrivateKey(fs.readFileSync(privatePath, 'utf8'));
} catch (err) {
  console.error('Could not load keys/dev-private.pem. Run `npm run generate:keys` first.');
  console.error(err.message);
  process.exit(1);
}

// PLACEHOLDER payload: field names and the event type must be confirmed
// against Belyfted's actual webhook schema.
const payload = {
  id: 'evt_example_0001',
  type: 'payment-created',
  createdAt: new Date().toISOString(),
  data: { amount: 5000, currency: 'NGN' },
};

const body = Buffer.from(JSON.stringify(payload), 'utf8');
const signature = crypto
  .sign('RSA-SHA256', body, { key: privateKey, padding: crypto.constants.RSA_PKCS1_PADDING })
  .toString('base64');

console.log('--- Sample signed webhook request (local testing only) ---\n');
console.log('Endpoint : POST http://localhost:3000/webhooks/belyfted');
console.log('Header   : Content-Type: application/json');
console.log('Header   : DigitalSignature: ' + signature);
console.log('Body     : ' + body.toString('utf8'));
console.log('\n--- Equivalent curl command ---\n');
console.log(
  `curl -i -X POST http://localhost:3000/webhooks/belyfted ` +
    `-H "Content-Type: application/json" ` +
    `-H "DigitalSignature: ${signature}" ` +
    `--data-binary '${body.toString('utf8')}'`
);
